INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist JSON immer das beste Format für WebServices?', 2, '[{"text": "Nein", "correct": true, "because": "XML oder Protobuf je nach Fall"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit JSON-Export und WebServices?', 3, '[{"text": "Datenaustausch", "correct": true, "because": "Interoperable Kommunikation"}, {"text": "Datenverschleierung", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Kompression", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen JSON für WebServices nützlich?', 5, '[{"text": "Lesbarkeit", "correct": true, "because": "Einfach für Mensch und Maschine"}, {"text": "Leichtgewichtigkeit", "correct": true, "because": "Geringer Overhead"}, {"text": "Hohe Pixeldichte", "correct": false, "because": "Irrelevant"}, {"text": "Statische Typisierung", "correct": false, "because": "JSON ist dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) REST-APIs nutzen oft JSON. b) JSON ist nur für Export geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "JSON auch für Import"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim JSON-Export für WebServices?', 4, '[{"text": "Datenstruktur", "correct": false, "because": "Kern des Formats"}, {"text": "API-Endpunkte", "correct": false, "because": "Ziel der Daten"}, {"text": "Farbkodierung", "correct": true, "because": "Kein Datenaustauschaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob JSON auch binäre Daten gut handhabt?', 2, '[{"text": "Nein", "correct": true, "because": "Textbasiert, Base64 nötig"}, {"text": "Ja", "correct": false, "because": "Nicht nativ unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches HTTP-Verfahren wähle ich für einen JSON-Export?', 3, '[{"text": "GET", "correct": true, "because": "Abruf von Daten"}, {"text": "DELETE", "correct": false, "because": "Löscht Daten"}, {"text": "TRACE", "correct": false, "because": "Diagnose, kein Export"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet JSON bei WebServices?', 5, '[{"text": "Interoperabilität", "correct": true, "because": "Plattformunabhängig"}, {"text": "Einfache Parsbarkeit", "correct": true, "because": "Leicht verarbeitbar"}, {"text": "Hohe Kompression", "correct": false, "because": "Keine Kompressionsfunktion"}, {"text": "Statische Struktur", "correct": false, "because": "Dynamisch anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) JSON ist schneller als XML. b) REST-APIs sind immer sicher. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit hängt von Implementierung ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen JSON-Export?', 4, '[{"text": "Datenstrukturierung", "correct": false, "because": "Grundlage des Exports"}, {"text": "Serialisierung", "correct": false, "because": "Konvertiert Daten"}, {"text": "Touch-Optimierung", "correct": true, "because": "Kein Exportfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist JSON nur für kleine Datenmengen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Skalierbar bei großen Daten"}, {"text": "Ja", "correct": false, "because": "Keine Größenbeschränkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche HTTP-Methoden nutze ich für WebServices mit JSON?', 4, '[{"text": "POST", "correct": true, "because": "Sendet JSON-Daten"}, {"text": "GET", "correct": true, "because": "Ruft JSON-Daten ab"}, {"text": "HEAD", "correct": false, "because": "Nur Metadaten"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass JSON-Export ohne WebServices nutzlos ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Lokal oder andere Protokolle möglich"}, {"text": "Ja", "correct": false, "because": "Export hat breite Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim JSON-Export für WebServices?', 3, '[{"text": "Datenkonsistenz", "correct": true, "because": "Sichert Verlässlichkeit"}, {"text": "Schnelle Serialisierung", "correct": false, "because": "Sekundär"}, {"text": "Grafische Darstellung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) REST-APIs sind zustandslos. b) JSON ist immer verschlüsselt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "JSON ist plaintext"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte verbessern WebServices mit JSON?', 5, '[{"text": "Schema-Definition", "correct": true, "because": "Klarheit der Struktur"}, {"text": "HTTP-Statuscodes", "correct": true, "because": "Kommunikationsfeedback"}, {"text": "Hohe Auflösung", "correct": false, "because": "Kein Datenaustauschaspekt"}, {"text": "Blinkende UI", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim JSON-Export unwichtig?', 3, '[{"text": "Datenintegrität", "correct": false, "because": "Sichert Korrektheit"}, {"text": "Serialisierungsformat", "correct": false, "because": "JSON als Standard"}, {"text": "Animationseffekte", "correct": true, "because": "Kein Exportfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich JSON ohne REST nutzen?', 3, '[{"text": "Ja", "correct": true, "because": "WebSockets oder Dateien möglich"}, {"text": "Nein", "correct": false, "because": "REST nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob WebServices mit JSON Authentifizierung brauchen?', 2, '[{"text": "Ja", "correct": true, "because": "Sicherheit oft erforderlich"}, {"text": "Nein", "correct": false, "because": "Öffentliche Daten möglich, aber selten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich für JSON-Export in WebServices?', 4, '[{"text": "Postman", "correct": true, "because": "Testet und exportiert JSON"}, {"text": "Notepad", "correct": false, "because": "Nur Editor"}, {"text": "Traceroute", "correct": false, "because": "Netzwerkdiagnose"}]');
